function i(t){if(!Number.isFinite(t)||!t||t<=0)return"0 B";const n=["B","KB","MB","GB"],r=Math.min(Math.floor(Math.log(t)/Math.log(1024)),n.length-1),a=t/1024**r;return`${a.toFixed(r===0||a>=10?0:1)} ${n[r]}`}function o(t){if(!Number.isFinite(t))return null;const n=Number(t);if(n<60)return`${Math.round(n)} s`;const r=Math.floor(n/60),a=Math.round(n%60);return`${r} min ${a.toString().padStart(2,"0")} s`}function u(t){if(!Number.isFinite(t))return"--:--";const n=Math.max(0,Math.floor(t));return`${Math.floor(n/60)}:${String(n%60).padStart(2,"0")}`}function e(t){return t?t.length>12?`${t.slice(0,8)}…`:t:"aguardando"}export{o as a,u as b,i as f,e as s};
